  let edge = smoothstep(1.0, 0.82, radius);
  let rim = smoothstep(0.62, 0.92, radius);
  let shade = mix(input.color.rgb, input.color.rgb * 0.35, rim);
  return vec4<f32>(shade, input.color.a * edge);
